    #[allow(clippy::too_many_arguments)]
    pub(crate) fn emit_stmt_for_iter<H: EmitHost>(&self, world: &EmitWorld<'_, '_, '_, '_>, walk: &mut EmitWalk, out: &mut EmitOut, host: &H, iter: &Expr, lends: bool, depth: i64, flow: EmitFlow, scope: &EmitScope) -> Result<(), Box<dyn std::error::Error>> {
        match iter {
            Expr::Range { .. } => {
                self.emit_core_bare_range(world, walk, out, host, iter, depth, flow, scope)?;
                return Ok(());
            },
            Expr::ListLit { items, .. } => {
                if !lends && !items.is_empty() {
                    out.push("[");
                    let mut i = 0;
                    for item in items.iter() {
                        if i > 0 { out.push(", "); }
                        self.emit_expr(world, walk, out, host, item, depth, flow, scope)?;
                        i += 1;
                    }
                    out.push("]");
                    return Ok(());
                }
            },
            _ => { },
        }
        if lends { self.emit_core_postfix_base(world, walk, out, host, iter, depth, flow, scope)?; } else { self.emit_expr(world, walk, out, host, iter, depth, flow, scope)?; }
        Ok(())
    }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
